window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9cf7a275434e852e"]={"versions": [{"id": "FIG-9cf7a275434e852e", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilablaufs im AUTOSAR E2E-Protokoll (End-to-End Communication Protection). Das Diagramm beschreibt den Teilschritt „Read Counter“ innerhalb der Prüffunktion <code>E2E_P07Check()</code> für das E2E-Profil 7 (typischerweise eingesetzt in 64-Bit-fähigen Umgebungen wie AUTOSAR Adaptive Platform und entsprechenden Classic-Konfigurationen).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext:</strong> Funktion bzw. Routine <code>E2E_P07Check()</code> (gekennzeichnet oben links durch das abgerundete Aktivitäten-/Subaktivitäts-Symbol).\n</li><li><strong>Datenstrukturen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li>Eingangsdaten-Array <code>Data</code> (Bytestream/Nutzdatenpuffer).\n</li><li>Offset-Konfiguration <code>Offset</code> (Byte-Offset des E2E-Headers im Datenstrom).\n</li><li>Zielvariable: lokale Variable <code>ReceivedCounter</code> vom Datentyp <code>uint32</code>.\n</li></ul>\n</li><li><strong>Knotenelemente:</strong>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node, ausgefüllter Kreis).\n</li><li>Aktionsknoten (Action / Call Behavior Action): „Copy bytes Data[Offset+12...Offset+15] in Big Endian order on uint32 local variable ReceivedCounter“.\n</li><li>Endknoten (Activity Final Node, Stopp-Symbol mit umrandetem Punkt).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start:</strong> Der Teilschritt beginnt am Initial Node bei Eintritt in die Extraktionsphase des Prüfablaufs.\n</li><li><strong>Extraktion:</strong> Aus dem Array <code>Data</code> werden exakt 4 Bytes an den Positionen <code>[Offset+12]</code> bis <code>[Offset+15]</code> in Big-Endian-Byte-Reihenfolge extrahiert und in die lokale 32-Bit-Variable <code>ReceivedCounter</code> kopiert.\n</li><li><strong>Abschluss:</strong> Die Kontrollflusskante führt unmittelbar zum Activity Final Node, womit der Teilschritt beendet ist und die nachfolgenden Prüfschritte (z. B. Read DataID / Read CRC / Plausibilitätsprüfung des Counters) anschließen können.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Relevanz:</strong> Die Operation ist normativ durch Anforderung <code>[PRS_E2E_00498]</code> vorgegeben.\n</li><li><strong>Implementierungshinweise:</strong>\n<ul class=\"fig-list\"><li>Der Counter in Profil 7 belegt ein 4-Byte-Feld (32 Bit) ab Byte 12 relativ zum konfigurierten Header-Offset (<code>Offset + 12</code> bis <code>Offset + 15</code>).\n</li><li>Unabhängig von der Host-Architektur (Little Endian oder Big Endian) muss die Byte-Transformation aus dem Netzwerk-Bytestream strikt in Big-Endian-Interpretation in das 32-Bit-Ganzzahlformat (<code>uint32</code>) erfolgen.\n</li><li>Das Array <code>Data</code> muss vor Zugriff auf mindestens <code>Offset + 16</code> Bytes Länge validiert sein, um Pufferüberläufe zu verhindern.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b078e521da0b56a3", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilablaufs im AUTOSAR E2E-Protokoll (End-to-End Communication Protection). Das Diagramm beschreibt den Teilschritt „Read Counter“ innerhalb der Prüffunktion <code>E2E_P07Check()</code> für das E2E-Profil 7 (typischerweise eingesetzt in 64-Bit-fähigen Umgebungen wie AUTOSAR Adaptive Platform und entsprechenden Classic-Konfigurationen).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext:</strong> Funktion bzw. Routine <code>E2E_P07Check()</code> (gekennzeichnet oben links durch das abgerundete Aktivitäten-/Subaktivitäts-Symbol).\n</li><li><strong>Datenstrukturen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li>Eingangsdaten-Array <code>Data</code> (Bytestream/Nutzdatenpuffer).\n</li><li>Offset-Konfiguration <code>Offset</code> (Byte-Offset des E2E-Headers im Datenstrom).\n</li><li>Zielvariable: lokale Variable <code>ReceivedCounter</code> vom Datentyp <code>uint32</code>.\n</li></ul>\n</li><li><strong>Knotenelemente:</strong>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node, ausgefüllter Kreis).\n</li><li>Aktionsknoten (Action / Call Behavior Action): „Copy bytes Data[Offset+12...Offset+15] in Big Endian order on uint32 local variable ReceivedCounter“.\n</li><li>Endknoten (Activity Final Node, Stopp-Symbol mit umrandetem Punkt).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start:</strong> Der Teilschritt beginnt am Initial Node bei Eintritt in die Extraktionsphase des Prüfablaufs.\n</li><li><strong>Extraktion:</strong> Aus dem Array <code>Data</code> werden exakt 4 Bytes an den Positionen <code>[Offset+12]</code> bis <code>[Offset+15]</code> in Big-Endian-Byte-Reihenfolge extrahiert und in die lokale 32-Bit-Variable <code>ReceivedCounter</code> kopiert.\n</li><li><strong>Abschluss:</strong> Die Kontrollflusskante führt unmittelbar zum Activity Final Node, womit der Teilschritt beendet ist und die nachfolgenden Prüfschritte (z. B. Read DataID / Read CRC / Plausibilitätsprüfung des Counters) anschließen können.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Relevanz:</strong> Die Operation ist normativ durch Anforderung <code>[PRS_E2E_00498]</code> vorgegeben.\n</li><li><strong>Implementierungshinweise:</strong>\n<ul class=\"fig-list\"><li>Der Counter in Profil 7 belegt ein 4-Byte-Feld (32 Bit) ab Byte 12 relativ zum konfigurierten Header-Offset (<code>Offset + 12</code> bis <code>Offset + 15</code>).\n</li><li>Unabhängig von der Host-Architektur (Little Endian oder Big Endian) muss die Byte-Transformation aus dem Netzwerk-Bytestream strikt in Big-Endian-Interpretation in das 32-Bit-Ganzzahlformat (<code>uint32</code>) erfolgen.\n</li><li>Das Array <code>Data</code> muss vor Zugriff auf mindestens <code>Offset + 16</code> Bytes Länge validiert sein, um Pufferüberläufe zu verhindern.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9cf7a275434e852e", "to": "FIG-b078e521da0b56a3", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
